```text
// Generated by bin/fm-pi-watch-extension.sh.
// Firstmate primary watcher bridge for Pi.
import { spawn, spawnSync } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

type ArmResult = {
  ok: boolean;
  message: string;
};

type LockOwnership = "owned" | "missing" | "other";

export default function (pi: any) {
  const fmHome = process.env.FM_HOME || process.env.FM_ROOT_OVERRIDE || process.cwd();
  const fmRoot = process.env.FM_ROOT_OVERRIDE || process.cwd();
  const state = process.env.FM_STATE_OVERRIDE || `${fmHome}/state`;
  const config = process.env.FM_CONFIG_OVERRIDE || `${fmHome}/config`;
  const armScript = `${fmRoot}/bin/fm-watch-arm.sh`;
  const marker = `${state}/.pi-watch-extension-loaded`;
  const extensionVersion = "sha256:216eda9a92fb5020ac63a0ec478be904f9a1f52f6b85c5cdd997af3079d1598e";
  let child: any = null;
  let seq = 0;

  function parentPid(pid: string): string {
    const result = spawnSync("ps", ["-o", "ppid=", "-p", pid], { encoding: "utf8" });
    if (result.status !== 0) return "";
    return result.stdout.trim();
  }

  function pidAlive(pid: string): boolean {
    try {
      process.kill(Number(pid), 0);
      return true;
    } catch {
      return false;
    }
  }

  function lockOwnership(): LockOwnership {
    let lockPid = "";
    try {
      lockPid = readFileSync(`${state}/.lock`, "utf8").trim();
    } catch {
      return "missing";
    }
    if (!/^[0-9]+$/.test(lockPid) || lockPid === "1") return "other";
    let pid = String(process.pid);
    for (let i = 0; i < 8; i += 1) {
      if (pid === lockPid) return "owned";
      pid = parentPid(pid);
      if (!pid || pid === "1") break;
    }
    return pidAlive(lockPid) ? "other" : "missing";
  }

  function sessionOwnsLock(): boolean {
    return lockOwnership() === "owned";
  }

  function markLoaded() {
    if (lockOwnership() === "other") return false;
    mkdirSync(state, { recursive: true });
    writeFileSync(marker, `${extensionVersion}\n${process.pid}\n`);
    return true;
  }

  function actionableLine(output: string): string {
    const lines = output.split(/\r?\n/);
    return lines.find((line) => /^(signal:|stale:|check:|heartbeat($|:))/.test(line)) || "";
  }

  function failureLine(stdout: string, stderr: string, code: number | null): string {
    const combined = `${stdout}\n${stderr}`.trim();
    const healthy = combined.split(/\r?\n/).find((line) => /^watcher: healthy\b/.test(line));
    if (healthy) return `watcher: FAILED - Pi extension arm child found an external healthy watcher instead of owning wake delivery\n${healthy}`;
    const failed = combined.split(/\r?\n/).find((line) => /^watcher: FAILED/.test(line));
    if (failed) return failed;
    if (code && code !== 0) return `watcher: FAILED - fm-watch-arm.sh exited ${code}${combined ? `\n${combined}` : ""}`;
    return "";
  }

  async function sendWake(message: string) {
    await pi.sendUserMessage(
      `FIRSTMATE WATCHER WAKE: ${message}\n\nRun bin/fm-wake-drain.sh first, handle the queued wake, then resume Pi supervision.`,
      { deliverAs: "followUp" },
    );
  }

  function startArm(): ArmResult {
    if (!sessionOwnsLock()) return { ok: false, message: "watcher: read-only - session lock is held by another firstmate session" };
    markLoaded();
    if (child) return { ok: true, message: "watcher: healthy - Pi extension already has an arm child" };
    const id = ++seq;
    const env = {
      ...process.env,
      FM_HOME: fmHome,
      FM_ROOT_OVERRIDE: fmRoot,
      FM_CONFIG_OVERRIDE: config,
      FM_WATCH_ARM_SCRIPT: armScript,
    };
    child = spawn("bash", ["-lc", "config_dir=\"${FM_CONFIG_OVERRIDE:-$FM_HOME/config}\"; [ -f \"$config_dir/x-mode.env\" ] && . \"$config_dir/x-mode.env\"; exec \"$FM_WATCH_ARM_SCRIPT\" --restart"], {
      cwd: fmRoot,
      env,
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk: Buffer) => {
      stdout += chunk.toString();
    });
    child.stderr.on("data", (chunk: Buffer) => {
      stderr += chunk.toString();
    });
    child.on("close", async (code: number | null) => {
      child = null;
      const reason = actionableLine(`${stdout}\n${stderr}`);
      const failure = reason ? "" : failureLine(stdout, stderr, code);
      if (!reason && !failure) return;
      try {
        await sendWake(reason || failure);
      } catch {
        // Pi owns delivery errors; fail open so the extension never wedges the session.
      }
    });
    child.on("error", async (error: Error) => {
      child = null;
      try {
        await sendWake(`watcher: FAILED - Pi extension arm child ${id} failed: ${error.message}`);
      } catch {
        // Fail open.
      }
    });
    return { ok: true, message: `watcher: started Pi extension arm child ${id}` };
  }

  pi.on?.("session_start", markLoaded);
  pi.on?.("session_shutdown", () => {
    if (child) child.kill("TERM");
    child = null;
  });

  pi.registerCommand?.("fm-watch-arm-pi", {
    description: "Arm firstmate watcher supervision through the Pi extension.",
    handler: async () => startArm().message,
  });

  pi.registerTool?.({
    name: "fm_watch_arm_pi",
    description: "Arm firstmate watcher supervision through the Pi extension.",
    parameters: {
      type: "object",
      properties: {},
      additionalProperties: false,
    },
    execute: async () => startArm(),
  });

  markLoaded();
}
```
</details>
- Outcome: 🔧 1 issue found → auto-fixed ✅ across 2 runs (39m5s)

## Pipeline

Updates from [git push no-mistakes](https://github.com/kunchenguid/no-mistakes)

<details>
<summary>✅ **intent** - passed</summary>

✅ No issues found.

</details>

<details>
<summary>✅ **Rebase** - passed</summary>

✅ No issues found.

</details>

<details>
<summary>🔧 **Review** - 5 issues found → auto-fixed (9) ✅</summary>

- 🚨 `tests/fm-pi-watch-extension.test.sh:1` - The new test files are added as mode 100644, but CI executes `tests/*.test.sh` directly, so the behavior-test job will hit permission denied. Mark `tests/fm-pi-watch-extension.test.sh`, `tests/fm-supervision-instructions.test.sh`, and `tests/fm-watch-checkpoint.test.sh` executable.
- 🚨 `.opencode/plugins/fm-primary-watch-arm.js:36` - The OpenCode watcher plugin decides whether it is in the primary once at load time and requires `root/state` to already exist. In a fresh checkout, or when `FM_HOME` points state/config outside the repo root, `primary` stays false or `shouldArm()` reads the wrong state, so the plugin never arms after `fm-session-start.sh` creates the real state dir. Resolve the effective home/state/config from `FM_HOME`/overrides and avoid making missing state at plugin load permanently disable supervision.
- 🚨 `.opencode/plugins/fm-primary-watch-arm.js:94` - After the watcher fires and injects a follow-up prompt, the plugin sets `skipNextIdle`; the next idle event is the moment after that follow-up finishes, so the handler returns without spawning the next watcher cycle. This leaves OpenCode supervision blind after the first wake unless another unrelated interaction happens. Do not skip the post-follow-up idle for the watcher-arm plugin.
- ⚠️ `bin/fm-session-start.sh:187` - For Pi primaries, session start regenerates `fm-primary-pi-watch.ts` and then immediately compares its mtime to the loaded marker. Because the generator rewrites the file every time, the extension is always newer than the marker, so a correctly loaded Pi session is still told to restart on every session start. Write only on content changes, or compare a stable content/version marker instead of the freshly rewritten mtime.
- ⚠️ `.pi/extensions/fm-primary-turnend-guard.ts:39` - The Pi passive turn-end follow-up still prepends the old universal `fm-watch-arm.sh` background-task instruction, which contradicts the new Pi extension protocol and the centralized guard text included below it. Update this adapter to use the same harness-neutral wording as the other turn-end paths.

🔧 Fix: Captain, harden watcher supervision regressions
3 warnings still open:
- ⚠️ `bin/fm-supervision-instructions.sh:150` - The new X-mode supervision block no longer renders the effective cadence file path. In supported `FM_HOME` or `FM_CONFIG_OVERRIDE` layouts, `config/x-mode.env` can live outside the repo root, so Claude/Codex/Grok operators following this emitted protocol will start watchers without the 30s X-mode cadence. Render the effective config path and use that path in the harness snippets/commands.
- ⚠️ `bin/fm-pi-watch-extension.sh:68` - The generated Pi watcher extension also sources `config/x-mode.env` relative to `fmRoot`. When Pi runs with `FM_HOME` or `FM_CONFIG_OVERRIDE` outside the repo root, `/fm-watch-arm-pi` starts `fm-watch-arm.sh` without the X-mode cadence, delaying X checks to the default interval. Resolve and source the effective config directory like the OpenCode plugin does.
- ⚠️ `.opencode/plugins/fm-primary-watch-arm.js:118` - OpenCode now arms the watcher on the same `session.idle` event used by the existing blind-turn guard, but the new handler only spawns `fm-watch-arm.sh` and returns before a fresh watcher beacon is guaranteed. Depending on plugin ordering/timing, the guard can run first or during arm confirmation and inject a spurious `TURN WOULD END BLIND` follow-up on every wake-handling turn. Coordinate the two OpenCode plugins so auto-arm gets a chance to establish supervision before the guard checks.

🔧 Fix: Captain, harden watcher supervision cadence
4 issues (1 error, 3 warnings) still open:
- 🚨 `.opencode/plugins/fm-primary-watch-arm.js:183` - The OpenCode auto-arm path spawns `fm-watch-arm.sh` whenever state says supervision is needed, but it never verifies that this OpenCode process owns the `state/.lock` acquired by `fm-session-start.sh`. A second read-only OpenCode session can therefore arm the watcher and receive wake prompts despite the lock refusal. Gate `ensureArm` on the current session owning the firstmate lock.
- ⚠️ `.opencode/plugins/fm-primary-watch-arm.js:195` - The coordinator used by the turn-end guard calls `ensureArm` directly, while the primary-root/secondmate/worktree scope check only exists in the direct idle handler. That lets the coordinator arm from a linked firstmate worktree or scoped-out home if `state/*.meta` or X mode exists. Move the `isPrimaryRoot` check into the shared arm path or coordinator.
- ⚠️ `bin/fm-supervision-instructions.sh:126` - Repair-line mode is X-mode blind: guard and turn-end callers do not pass `--x-mode`, and these harness-specific repair commands omit sourcing the effective `config/x-mode.env`. In X mode, following a blind-turn repair can restart supervision at the default cadence instead of the required 30s X polling cadence.
- ⚠️ `bin/fm-pi-watch-extension.sh:12` - The `mktemp` template has a suffix after the Xs. On macOS/BSD `mktemp`, this creates the literal file `fm-primary-pi-watch.XXXXXX.ts`, so an interrupted or concurrent generation can leave a fixed stale temp file and break later Pi extension generation. Use a portable template with Xs at the end.

🔧 Fix: Harden watcher supervision ownership
1 warning still open:
- ⚠️ `bin/fm-pi-watch-extension.sh:37` - The Pi loaded marker is only a timestamp, and the generated extension refreshes it whenever the old in-memory extension arms. If `fm-primary-pi-watch.ts` changes while Pi is still running, using the old `/fm-watch-arm-pi` command can make `.pi-watch-extension-loaded` newer than the regenerated file, so later session starts stop warning even though Pi has not loaded the new extension. Store and compare a generated content/version marker instead of relying on mtime alone.

🔧 Fix: Captain, harden Pi extension marker
2 warnings still open:
- ⚠️ `bin/fm-session-start.sh:192` - The Pi load diagnostic trusts a persistent marker that only contains the generated extension version. After one Pi session loads the extension, that marker can remain in state; a later Pi session started without `-e` will still compare equal here and suppress the `not loaded` warning. Include a current session/process identifier in the marker and validate it against the active lock, or otherwise make stale markers fail closed.
- ⚠️ `docs/supervision-protocols/pi.md:5` - The Pi supervision block hardcodes `state/fm-primary-pi-watch.ts`, but the generator writes to the effective state directory (`FM_HOME`/`FM_STATE_OVERRIDE`). In supported non-repo-root homes this points operators at the wrong extension path, so a restart can leave `/fm-watch-arm-pi` unavailable. Render the computed `pi_ext` path instead of a literal repo-relative path.

🔧 Fix: Captain, harden Pi supervision restart checks
4 issues (3 errors, 1 warning) still open:
- 🚨 `bin/fm-pi-watch-extension.sh:51` - The generated Pi extension writes `.pi-watch-extension-loaded` on load and can later spawn `fm-watch-arm.sh` without checking that `state/.lock` names the current Pi process. A second Pi session that lost the session-start lock can overwrite the loaded marker and arm or receive watcher wakes from a read-only session. Gate marker writes and arm attempts on session-lock ownership.
- ⚠️ `bin/fm-spawn.sh:626` - Pi secondmate watcher generation sets `FM_HOME` and `FM_ROOT_OVERRIDE` to the secondmate home but leaves the primary `FM_STATE_OVERRIDE` inherited. In supported override layouts, the extension is written to the primary override state while the launch points Pi at `$PROJ_ABS/state/fm-primary-pi-watch.ts`, so the secondmate starts without the generated watcher extension. Clear or set operational overrides for this generation command.
- 🚨 `bin/fm-watch-checkpoint.sh:100` - If a prior watcher still holds `.watch.lock`, `fm-watch.sh` exits 0 with `watcher: already running`; this checkpoint falls through, prints that non-actionable output, and exits 0. Codex then has no foreground wait attached, while the turn-end guard can still pass on the external beacon. Treat singleton no-op output as an ownership failure, or restart/take over the watcher before returning success.
- 🚨 `.opencode/plugins/fm-primary-watch-arm.js:128` - For OpenCode, `watcher: healthy` means the just-spawned `fm-watch-arm.sh` found another watcher and exited, leaving the plugin with no child that can call `promptAsync` when that external watcher fires. Marking both `started` and `healthy` as `armed` lets the coordinator suppress the turn-end guard while OpenCode is not actually subscribed to a wake. Restart/adopt the watcher, or treat `healthy` from a new child as not armed.

🔧 Fix: Harden watcher ownership checks
2 issues (1 error, 1 warning) still open:
- 🚨 `docs/supervision-protocols/pi.md:5` - The Pi session-start block tells operators to restart Pi with only the generated watcher extension, but the existing no-turn-blind backstop still lives in `.pi/extensions/fm-primary-turnend-guard.ts` and the generated watcher extension does not register `turn_end`. Following this emitted block can relaunch a Pi primary without the turn-end follow-up guard, so either load both extensions in the rendered Pi command or fold the turn-end guard into the generated extension.
- ⚠️ `bin/fm-pi-watch-extension.sh:75` - `markLoaded()` refuses to write the loaded marker unless `state/.lock` already names the current Pi process. On a normal fresh Pi launch, the extension loads before `fm-session-start.sh` creates that lock, so a correctly launched Pi primary cannot mark itself loaded before the session-start diagnostic runs and will be told to restart anyway. Allow the initial no-lock marker and validate it after lock acquisition, while still refusing to overwrite when another live lock exists.

🔧 Fix: Captain, harden Pi supervision loading
2 issues (1 error, 1 warning) still open:
- 🚨 `bin/fm-spawn.sh:320` - Pi secondmate launches now load only the generated watcher extension. Since a secondmate is itself a firstmate primary, this starts Pi secondmates without `.pi/extensions/fm-primary-turnend-guard.ts`, so the no-blind-turn backstop is absent; include the turn-end guard extension in the secondmate Pi launch template too.
- ⚠️ `bin/fm-session-start.sh:205` - The Pi session-start diagnostic validates only `.pi-watch-extension-loaded`. A Pi session launched with the watcher extension but without the turn-end guard can pass this check and suppress the restart warning even though the emitted protocol requires both extensions; add a current-process marker/check for the turn-end guard or fold the guard into the generated extension.

🔧 Fix: Captain, require Pi guard extension loading
2 issues (1 error, 1 warning) still open:
- 🚨 `bin/fm-pi-watch-extension.sh:145` - If `fm-watch-arm.sh --restart` exits with `watcher: healthy ...`, the Pi extension treats it as a quiet success and drops the child. That leaves Pi with no attached process to call `sendUserMessage` when the external watcher later fires, while the turn-end guard still sees a fresh watcher beacon and allows the turn. Treat healthy output from the spawned child as an unowned-watcher failure/wake instead of returning silently.
- ⚠️ `bin/fm-bootstrap.sh:394` - This X-mode opt-out remediation still hardcodes `bin/fm-watch-arm.sh --restart`. Under the new harness-specific supervision model, that is the wrong recovery shape for Codex, Pi, and OpenCode primaries; route this through the harness-aware supervision instruction renderer instead.

🔧 Fix: Captain, harden watcher supervision recovery
✅ Re-checked - no issues remain.

</details>

<details>
<summary>🔧 **Test** - 1 issue found → auto-fixed ✅</summary>

- 🚨 tests failed with exit code 1
