// Product-level transcript of what a Pi primary agent sees from fm_watch_arm_pi
// across the real session lifecycle: startup, a `/new` restart, an overlapping
// extension bind, the deferred binding after its rival ends, and terminal quit.
// Run once per extension build (pre-fix and post-fix) and diff the transcripts.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

const armLog = process.env.FM_ARM_LOG;
const childPidFile = process.env.FM_CHILD_PID_FILE;

function makePi(label) {
  const handlers = new Map();
  let tool = null;
  const pi = {
    on(event, handler) {
      handlers.set(event, handler);
    },
    registerCommand() {},
    registerTool(candidate) {
      if (candidate.name === "fm_watch_arm_pi") tool = candidate;
    },
    sendUserMessage: async () => {},
    events: { on() {} },
  };
  return { label, pi, handlers, getTool: () => tool };
}

function pidAlive(pid) {
  try {
    process.kill(Number(pid), 0);
    return true;
  } catch {
    return false;
  }
}

function liveArmPids() {
  if (!existsSync(armLog)) return [];
  return readFileSync(armLog, "utf8")
    .trim()
    .split(/\n/)
    .filter(Boolean)
    .map((line) => /pid=(\d+)/.exec(line)?.[1] || "")
    .filter(Boolean)
    .filter(pidAlive);
}

async function waitFor(pred, attempts = 250) {
  for (let i = 0; i < attempts; i += 1) {
    if (pred()) return true;
    await new Promise((r) => setTimeout(r, 20));
  }
  return false;
}

const exitBaseline = process.listenerCount("exit");
function exitFallbacks() {
  return process.listenerCount("exit") - exitBaseline;
}

function say(line) {
  process.stdout.write(`${line}\n`);
}

function state() {
  return `live arm children=${liveArmPids().length}  process-exit fallbacks=${exitFallbacks()}`;
}

async function armThrough(binding, callId) {
  const result = await binding.getTool().execute(callId, {}, undefined, undefined, {});
  const text = String(result.details?.message ?? result.content?.[0]?.text ?? "");
  say(`  ${binding.label} calls fm_watch_arm_pi`);
  say(`    -> ok=${result.details?.ok} ${text.split(";")[0]}`);
  return result;
}

writeFileSync(`${process.env.FM_HOME}/state/.lock`, `${process.pid}\n`);
const mod = await import(pathToFileURL(process.env.PLUGIN).href);

say("=== 1. Pi starts, extension binds, session_start(startup) ===");
let owner = makePi("session A");
mod.default(owner.pi);
await owner.handlers.get("session_start")?.({ type: "session_start", reason: "startup" }, {});
await armThrough(owner, "startup");
await waitFor(() => liveArmPids().length === 1);
say(`  ${state()}`);
const startupChild = readFileSync(childPidFile, "utf8").trim();

say("");
say("=== 2. Operator runs /new: Pi shuts the session down and binds a replacement ===");
await owner.handlers.get("session_shutdown")?.({ type: "session_shutdown", reason: "new" }, {});
await waitFor(() => !pidAlive(startupChild));
say(`  after session_shutdown(new): ${state()}`);
const replacement = makePi("session B");
mod.default(replacement.pi);
await replacement.handlers.get("session_start")?.({ type: "session_start", reason: "new" }, {});
await armThrough(replacement, "after-new");
await waitFor(() => liveArmPids().length === 1);
say(`  ${state()}`);
owner = replacement;
const ownerChild = readFileSync(childPidFile, "utf8").trim();

say("");
say("=== 3. An extra extension bind arrives while session B is still live ===");
const overlap = makePi("session C (overlapping bind)");
mod.default(overlap.pi);
await overlap.handlers.get("session_start")?.({ type: "session_start", reason: "startup" }, {});
await armThrough(overlap, "overlapping-bind");
say(`  session B child still alive=${pidAlive(ownerChild)}  ${state()}`);
await armThrough(owner, "owner-after-overlap");

say("");
say("=== 4. Session B shuts down; the deferred bind C never became the owner ===");
await owner.handlers.get("session_shutdown")?.({ type: "session_shutdown", reason: "new" }, {});
await waitFor(() => !pidAlive(ownerChild));
await armThrough(overlap, "deferred-after-owner-end");
say(`  ${state()}`);

say("");
say("=== 5. Session C receives its own session_start and takes over ===");
await overlap.handlers.get("session_start")?.({ type: "session_start", reason: "new" }, {});
await armThrough(overlap, "deferred-own-start");
await waitFor(() => liveArmPids().length === 1);
say(`  ${state()}`);
const finalChild = readFileSync(childPidFile, "utf8").trim();

say("");
say("=== 6. Operator quits Pi for real ===");
await overlap.handlers.get("session_shutdown")?.({ type: "session_shutdown", reason: "quit" }, {});
await waitFor(() => !pidAlive(finalChild));
await armThrough(overlap, "after-quit");
say(`  ${state()}`);
process.exit(0);
```
